head.b:skin:
:root{
  --color-bg:#ffffff;
  --color-bg-soft:#f7f8fa;
  --color-border:#e7e9ec;
  --color-text:#1b1d21;
  --color-text-soft:#6b7280;
  --color-point:#3d6bff;
  --color-point-soft:#eef2ff;
  --radius:14px;
  --max-width:1180px;
  font-family:-apple-system,BlinkMacSystemFont,"Apple SD Gothic Neo","Pretendard","Noto Sans KR",sans-serif;
}
*{box-sizing:border-box;}
body{margin:0;background:var(--color-bg);color:var(--color-text);line-height:1.55;}
a{color:inherit;text-decoration:none;}
img{max-width:100%;display:block;}
.wrap{max-width:var(--max-width);margin:0 auto;padding:0 20px;}

.site-header{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.92);backdrop-filter:blur(8px);border-bottom:1px solid var(--color-border);}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;height:64px;gap:16px;}
.site-title{font-size:20px;font-weight:800;letter-spacing:-.02em;flex-shrink:0;}
.site-title a{color:var(--color-text);}
.site-title .point{color:var(--color-point);}
.menu-btn{display:none;border:1px solid var(--color-border);background:var(--color-bg);border-radius:8px;width:36px;height:36px;font-size:16px;cursor:pointer;flex-shrink:0;}
.site-nav{overflow-x:auto;overflow-y:hidden;-ms-overflow-style:none;scrollbar-width:none;flex:1;}
.site-nav::-webkit-scrollbar{display:none;height:0;width:0;}
.site-nav ul{list-style:none;display:flex;gap:18px;margin:0;padding:0;white-space:nowrap;flex-wrap:nowrap;}
.site-nav li{flex-shrink:0;}
.site-nav a{font-size:14px;font-weight:600;color:var(--color-text-soft);padding:8px 2px;white-space:nowrap;border-bottom:2px solid transparent;}
.site-nav a:hover{color:var(--color-point);}
.site-nav a.active{color:var(--color-point);border-bottom-color:var(--color-point);}

.hero{padding:32px 0 20px;text-align:center;}
.hero h1{font-size:28px;font-weight:800;margin:0 0 10px;letter-spacing:-.02em;}
.hero p{color:var(--color-text-soft);font-size:15px;margin:0;}

.search-box{max-width:560px;margin:0 auto 18px;}
.search-box input{width:100%;font-size:15px;padding:13px 16px;border:1px solid var(--color-border);border-radius:999px;outline:none;box-sizing:border-box;}
.search-box input:focus{border-color:var(--color-point);}
.trending-tags{display:flex;align-items:center;gap:8px;flex-wrap:wrap;max-width:var(--max-width);margin:0 auto 28px;padding:0 20px;}
.trending-tags .label{font-size:12px;color:var(--color-text-soft);flex-shrink:0;}
.tag-chip{font-size:12px;font-weight:600;color:var(--color-text-soft);background:var(--color-bg-soft);border:1px solid var(--color-border);border-radius:999px;padding:6px 12px;cursor:pointer;}
.tag-chip:hover,.tag-chip.active{color:var(--color-point);border-color:var(--color-point);background:var(--color-point-soft);}
.no-results{display:none;color:var(--color-text-soft);font-size:14px;padding:20px 0;}
.no-results.show{display:block;}

.body-layout{display:flex;gap:28px;align-items:flex-start;max-width:var(--max-width);margin:0 auto;padding:0 20px 60px;}
.app-sidebar{width:200px;flex-shrink:0;position:sticky;top:84px;}
.app-sidebar .sidebar-title{font-size:12px;font-weight:700;color:var(--color-text-soft);margin:0 0 10px;padding-left:10px;}
.app-sidebar nav{display:flex;flex-direction:column;gap:2px;}
.app-sidebar a{display:flex;align-items:center;gap:10px;font-size:14px;font-weight:600;color:var(--color-text);padding:9px 10px;border-radius:8px;}
.app-sidebar a:hover{background:var(--color-bg-soft);}
.app-sidebar a.active{background:var(--color-point-soft);color:var(--color-point);}
.app-sidebar .dot{width:8px;height:8px;border-radius:999px;flex-shrink:0;}
.sidebar-overlay{display:none;position:fixed;inset:0;background:rgba(17,17,20,.4);z-index:90;}
.main-col{flex:1;min-width:0;}
.side-col{width:300px;flex-shrink:0;}
@media (max-width:980px){.side-col{display:none;}}
@media (max-width:860px){
  .menu-btn{display:block;}
  .app-sidebar{position:fixed;top:0;left:0;bottom:0;width:240px;background:var(--color-bg);z-index:100;padding:20px 16px;transform:translateX(-100%);transition:transform .2s;overflow-y:auto;}
  .app-sidebar.open{transform:translateX(0);}
  .sidebar-overlay.open{display:block;}
}

.cat-section{padding:36px 0 8px;border-top:1px solid var(--color-border);scroll-margin-top:76px;}
.cat-section:first-child{border-top:none;}
.cat-section h2{font-size:22px;font-weight:800;margin:0 0 4px;}
.cat-section .cat-updated{font-size:12px;color:var(--color-text-soft);margin:0 0 6px;}
.cat-section .cat-intro{font-size:14px;color:var(--color-text-soft);margin:0 0 18px;}

.rank-grid{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:14px;}
.rank-card{position:relative;display:flex;flex-direction:column;padding:18px 16px 16px;border:1px solid var(--color-border);border-radius:var(--radius);background:var(--color-bg);cursor:pointer;transition:box-shadow .15s,border-color .15s;}
.rank-card:hover{box-shadow:0 4px 16px rgba(0,0,0,.06);border-color:var(--color-point);}
.rank-card.is-hidden{display:none;}
.rank-num{position:absolute;top:10px;left:38px;z-index:2;font-size:11px;font-weight:800;color:#fff;background:var(--color-point);border-radius:999px;width:20px;height:20px;display:flex;align-items:center;justify-content:center;box-shadow:0 0 0 2px var(--color-bg);}
.rank-logo{width:48px;height:48px;border-radius:12px;background:var(--color-point-soft);color:var(--color-point);display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:800;overflow:hidden;margin:8px 0 12px;position:relative;z-index:1;}
.rank-logo img{width:28px;height:28px;object-fit:contain;}
.rank-logo-fallback{display:none;align-items:center;justify-content:center;width:100%;height:100%;}
.rank-info{display:flex;flex-direction:column;flex:1;}
.rank-info .rank-name{font-weight:700;font-size:15px;margin:0 0 4px;}
.rank-info .rank-summary{font-size:13px;color:var(--color-text-soft);margin:0;flex:1;}
.rank-rating{display:flex;align-items:center;gap:4px;margin-top:10px;}
.rank-rating .star{font-size:13px;color:#f5b400;}
.rank-rating .score{font-size:12px;color:var(--color-text-soft);margin-left:2px;}
.rank-tags{display:flex;gap:6px;margin-top:8px;flex-wrap:wrap;}
.fav-btn{position:absolute;top:10px;right:10px;width:28px;height:28px;border:none;background:none;font-size:17px;color:var(--color-text-soft);cursor:pointer;line-height:1;}
.fav-btn.active{color:#f5b400;}
.rank-tags span{font-size:11px;background:var(--color-bg-soft);color:var(--color-text-soft);border-radius:6px;padding:2px 7px;}
.rank-visit{align-self:flex-start;margin-top:12px;font-size:12px;font-weight:700;color:var(--color-point);border:1px solid var(--color-point);border-radius:8px;padding:6px 12px;white-space:nowrap;}

.modal-overlay{position:fixed;inset:0;background:rgba(17,17,20,.55);display:none;align-items:center;justify-content:center;z-index:200;padding:20px;}
.modal-overlay.open{display:flex;}
.modal-box{background:#fff;border-radius:18px;max-width:520px;width:100%;max-height:85vh;overflow-y:auto;padding:28px;position:relative;}
.modal-box .modal-close{position:absolute;top:14px;right:16px;background:none;border:none;font-size:20px;cursor:pointer;color:var(--color-text-soft);}
.modal-box h3{margin:4px 0 6px;font-size:19px;}
.modal-box .modal-meta{font-size:13px;color:var(--color-text-soft);margin-bottom:14px;}
.modal-box .modal-link{display:inline-block;margin-top:14px;background:var(--color-point);color:#fff;font-weight:700;font-size:14px;padding:10px 18px;border-radius:10px;}
.helpful-btn{font-size:12px;border:1px solid var(--color-border);background:var(--color-bg);border-radius:8px;padding:6px 10px;cursor:pointer;color:var(--color-text-soft);margin-top:14px;}
.helpful-btn.voted{border-color:var(--color-point);color:var(--color-point);}
.rank-detail{display:none;}

.ad-slot{margin:24px 0;text-align:center;}
.ad-slot .ad-label{font-size:11px;color:var(--color-text-soft);margin-bottom:6px;letter-spacing:.05em;}
.ad-sidebar{position:sticky;top:84px;}
.ad-mobile-only{display:none;}
@media (max-width:980px){.ad-mobile-only{display:block;} .ad-desktop-only{display:none;}}

.site-footer{border-top:1px solid var(--color-border);padding:32px 0;margin-top:20px;background:var(--color-bg-soft);}
.site-footer .wrap{display:flex;flex-direction:column;gap:14px;align-items:center;text-align:center;}
.site-footer p{font-size:12px;color:var(--color-text-soft);margin:0;}

.site-search{display:flex;align-items:center;background:var(--color-bg-soft);border:1px solid var(--color-border);border-radius:10px;padding:4px 4px 4px 12px;flex-shrink:0;}
.site-search input{border:none;background:none;font-size:13px;outline:none;width:120px;}
.site-search button{border:none;background:none;cursor:pointer;font-size:14px;padding:6px 10px;}

@media (max-width:680px){
  .rank-grid{grid-template-columns:repeat(2,1fr);}
  .site-search input{width:80px;}
}

body.script:
//
document.addEventListener('click', function(e){
  var favBtn = e.target.closest('.fav-btn');
  if(favBtn){
    e.stopPropagation();
    var favKey = 'fav_' + favBtn.getAttribute('data-fav');
    var isFav = localStorage.getItem(favKey) === '1';
    if(isFav){
      localStorage.removeItem(favKey);
      favBtn.classList.remove('active');
      favBtn.textContent = '☆';
    } else {
      localStorage.setItem(favKey, '1');
      favBtn.classList.add('active');
      favBtn.textContent = '★';
    }
    return;
  }
  var helpfulBtn = e.target.closest('.helpful-btn');
  if(helpfulBtn){
    e.stopPropagation();
    var key = 'helpful_' + helpfulBtn.getAttribute('data-id');
    var voted = localStorage.getItem(key) === '1';
    var countEl = helpfulBtn.querySelector('.count');
    var count = parseInt(countEl.textContent, 10) || 0;
    if(voted){
      localStorage.removeItem(key);
      helpfulBtn.classList.remove('voted');
      countEl.textContent = Math.max(0, count - 1);
    } else {
      localStorage.setItem(key, '1');
      helpfulBtn.classList.add('voted');
      countEl.textContent = count + 1;
    }
    return;
  }
  var card = e.target.closest('.rank-card');
  if(card){
    var id = card.getAttribute('data-modal');
    var detail = document.getElementById(id);
    var overlay = document.getElementById('rank-modal-overlay');
    if(detail && overlay){
      overlay.querySelector('.modal-box').innerHTML = detail.innerHTML + '<button class="modal-close" aria-label="닫기">×</button>';
      overlay.classList.add('open');
      var newBtn = overlay.querySelector('.helpful-btn');
      if(newBtn){
        var k = 'helpful_' + newBtn.getAttribute('data-id');
        if(localStorage.getItem(k) === '1') newBtn.classList.add('voted');
      }
    }
  }
  if(e.target.classList.contains('modal-close') || e.target.id === 'rank-modal-overlay'){
    var ov = document.getElementById('rank-modal-overlay');
    if(ov) ov.classList.remove('open');
  }
});
document.addEventListener('DOMContentLoaded', function(){
  document.querySelectorAll('.helpful-btn[data-id]').forEach(function(btn){
    if(!btn.closest('.rank-detail')){
      var k = 'helpful_' + btn.getAttribute('data-id');
      if(localStorage.getItem(k) === '1') btn.classList.add('voted');
    }
  });
  document.querySelectorAll('.fav-btn[data-fav]').forEach(function(btn){
    var k = 'fav_' + btn.getAttribute('data-fav');
    if(localStorage.getItem(k) === '1'){
      btn.classList.add('active');
      btn.textContent = '★';
    }
  });

  var sections = Array.prototype.slice.call(document.querySelectorAll('.cat-section'));
  var navLinks = Array.prototype.slice.call(document.querySelectorAll(".site-nav a[href^='#']"));
  var sidebarLinks = Array.prototype.slice.call(document.querySelectorAll(".app-sidebar a[href^='#']"));
  function setActive(id){
    navLinks.forEach(function(a){ a.classList.toggle('active', a.getAttribute('href') === '#' + id); });
    sidebarLinks.forEach(function(a){ a.classList.toggle('active', a.getAttribute('href') === '#' + id); });
  }
  if(sections.length && 'IntersectionObserver' in window){
    var observer = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(entry.isIntersecting) setActive(entry.target.id);
      });
    }, { rootMargin: '-90px 0px -70% 0px' });
    sections.forEach(function(sec){ observer.observe(sec); });
  }
  navLinks.concat(sidebarLinks).forEach(function(a){
    a.addEventListener('click', function(){
      setActive(a.getAttribute('href').slice(1));
      sidebar.classList.remove('open');
      sidebarOverlay.classList.remove('open');
    });
  });

  var sidebar = document.getElementById('app-sidebar');
  var sidebarOverlay = document.getElementById('sidebar-overlay');
  var sidebarToggle = document.getElementById('sidebar-toggle');
  if(sidebarToggle){
    sidebarToggle.addEventListener('click', function(){
      sidebar.classList.add('open');
      sidebarOverlay.classList.add('open');
    });
  }
  if(sidebarOverlay){
    sidebarOverlay.addEventListener('click', function(){
      sidebar.classList.remove('open');
      sidebarOverlay.classList.remove('open');
    });
  }

  var searchInput = document.getElementById('tool-search');
  var noResults = document.getElementById('no-results');
  var allCards = Array.prototype.slice.call(document.querySelectorAll('.rank-card'));
  var tagChips = Array.prototype.slice.call(document.querySelectorAll('.tag-chip'));
  function applyFilter(query){
    query = query.trim().toLowerCase();
    var visibleCount = 0;
    allCards.forEach(function(card){
      var text = (card.getAttribute('data-name') + ' ' + card.getAttribute('data-tags')).toLowerCase();
      var match = !query || text.indexOf(query) !== -1;
      card.classList.toggle('is-hidden', !match);
      if(match) visibleCount++;
    });
    sections.forEach(function(sec){
      var hasVisible = sec.querySelector('.rank-card:not(.is-hidden)');
      sec.style.display = (!query || hasVisible) ? '' : 'none';
    });
    if(noResults) noResults.classList.toggle('show', query !== '' && visibleCount === 0);
  }
  if(searchInput){
    searchInput.addEventListener('input', function(){
      tagChips.forEach(function(c){ c.classList.remove('active'); });
      applyFilter(searchInput.value);
    });
  }
  tagChips.forEach(function(chip){
    chip.addEventListener('click', function(){
      var active = chip.classList.contains('active');
      tagChips.forEach(function(c){ c.classList.remove('active'); });
      if(active){
        searchInput.value = '';
        applyFilter('');
      } else {
        chip.classList.add('active');
        searchInput.value = chip.getAttribute('data-tag');
        applyFilter(chip.getAttribute('data-tag'));
      }
    });
  });
});
//
